WITH cleaned AS (SELECT *, UPPER(status) AS status_upper, CASE WHEN account_type IN ('LOAN', 'CHECKING') THEN 'Core' ELSE 'Other' END AS account_type_group FROM accounts WHERE customer_id IS NOT NULL) SELECT s.id, s.account_type, s.balance, s.opened_date, s.status, s.account_type_group, latest.transaction_txn_time, latest.txn_type FROM cleaned s JOIN LATERAL (SELECT c.txn_time AS transaction_txn_time, c.txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE
